-- Column definitions from the supplied production schema report; synthetic data only.
CREATE ROLE anon; CREATE ROLE authenticated;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz,deleted_at timestamptz,banned_until timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT jsonb_build_object('email',email) FROM auth.users WHERE id=auth.uid() $$;
GRANT USAGE ON SCHEMA auth TO anon,authenticated;
CREATE TABLE public.profiles("id" uuid NOT NULL DEFAULT gen_random_uuid(),"user_id" uuid,"name" text NOT NULL,"logo_url" text,"seal_url" text,"gstin" text,"pan" text,"email" text,"phone" text,"address" text,"website" text,"currency" text DEFAULT 'INR'::text,"bank_name" text,"bank_account_no" text,"bank_ifsc" text,"bank_holder" text,"bank_branch" text,"default_terms" text,"col_name_description" text DEFAULT 'Description'::text,"col_name_quantity" text DEFAULT 'Quantity'::text,"col_name_unit" text DEFAULT 'Unit'::text,"col_name_rate" text DEFAULT 'Rate'::text,"col_name_amount" text DEFAULT 'Amount'::text,"invoice_prefix" text DEFAULT 'INV/'::text,"invoice_start_number" integer DEFAULT 1001,"proforma_prefix" text DEFAULT 'PI/'::text,"proforma_start_number" integer DEFAULT 1001,"quotation_prefix" text DEFAULT 'QTN/'::text,"quotation_start_number" integer DEFAULT 1001,"work_order_prefix" text DEFAULT 'WO/'::text,"work_order_start_number" integer DEFAULT 1001,"created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()),"google_sheets_url" text,"show_bank_details" boolean DEFAULT true,"approver_email" text,"non_tax_prefix" text DEFAULT 'NT/'::text,"non_tax_start_number" integer DEFAULT 1001);
CREATE TABLE public.documents("id" uuid NOT NULL DEFAULT gen_random_uuid(),"user_id" uuid,"company_id" uuid,"document_type" text NOT NULL,"document_number" text NOT NULL,"sequence_number" integer NOT NULL,"customer_id" uuid,"customer_name" text NOT NULL,"customer_email" text,"customer_phone" text,"customer_address" text,"customer_gstin" text,"date" date NOT NULL DEFAULT CURRENT_DATE,"col_name_description" text NOT NULL DEFAULT 'Description'::text,"col_name_quantity" text NOT NULL DEFAULT 'Quantity'::text,"col_name_unit" text NOT NULL DEFAULT 'Unit'::text,"col_name_rate" text NOT NULL DEFAULT 'Rate'::text,"col_name_amount" text NOT NULL DEFAULT 'Amount'::text,"subtotal" numeric NOT NULL DEFAULT 0,"tax_total" numeric NOT NULL DEFAULT 0,"discount_total" numeric NOT NULL DEFAULT 0,"total" numeric NOT NULL DEFAULT 0,"notes" text,"terms" text,"created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()),"created_by_email" text,"whatsapp_sent_by_email" text,"whatsapp_sent_at" timestamp with time zone,"status" text DEFAULT 'pending_approval'::text,"approved_by_email" text,"approved_at" timestamp with time zone,"advance" numeric NOT NULL DEFAULT 0);
CREATE TABLE public.document_items("id" uuid NOT NULL DEFAULT gen_random_uuid(),"document_id" uuid,"service_id" uuid,"description" text NOT NULL,"quantity" numeric NOT NULL DEFAULT 1,"days" numeric NOT NULL DEFAULT 1,"rate" numeric NOT NULL DEFAULT 0,"unit" text DEFAULT 'nos'::text,"hsn_sac" text,"amount" numeric NOT NULL DEFAULT 0,"sort_order" integer NOT NULL DEFAULT 0,"gst_percentage" numeric NOT NULL DEFAULT 0);
CREATE TABLE public.comparison_document_data("id" uuid NOT NULL DEFAULT gen_random_uuid(),"document_id" uuid,"options_data" jsonb NOT NULL,"created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()));
CREATE TABLE public.leads("id" uuid NOT NULL DEFAULT gen_random_uuid(),"company_id" uuid NOT NULL,"customer_id" uuid,"customer_name" text NOT NULL,"company_name" text,"phone" text,"whatsapp_number" text,"address" text,"location" text,"business_type" text,"lead_source" text NOT NULL DEFAULT 'other'::text,"source_details" text,"service_required" text,"vehicle_service_type" text,"required_date" date,"campaign_location" text,"number_of_days" integer,"priority" text NOT NULL DEFAULT 'warm'::text,"assigned_telecaller_email" text,"status" text NOT NULL DEFAULT 'new'::text,"next_follow_up_at" timestamp with time zone,"notes" text,"remarks" text,"created_at" timestamp with time zone NOT NULL DEFAULT now(),"updated_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.lead_activities("id" uuid NOT NULL DEFAULT gen_random_uuid(),"company_id" uuid,"lead_id" uuid,"type" text NOT NULL,"notes" text NOT NULL,"performed_by" text,"created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()));
CREATE TABLE public.follow_ups("id" uuid NOT NULL DEFAULT gen_random_uuid(),"company_id" uuid NOT NULL,"customer_id" uuid NOT NULL,"follow_up_date" date NOT NULL,"follow_up_time" time without time zone,"notes" text,"assigned_staff_email" text,"status" text NOT NULL DEFAULT 'pending'::text,"created_at" timestamp with time zone NOT NULL DEFAULT now(),"updated_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public.crm_quotations("id" uuid NOT NULL DEFAULT gen_random_uuid(),"company_id" uuid,"lead_id" uuid,"quotation_number" text NOT NULL,"date" date NOT NULL,"valid_until" date,"customer_name" text NOT NULL,"company_name" text,"phone" text NOT NULL,"whatsapp_number" text,"location" text,"service_summary" text NOT NULL,"items" jsonb NOT NULL DEFAULT '[]'::jsonb,"subtotal" numeric NOT NULL DEFAULT 0,"cgst" numeric NOT NULL DEFAULT 0,"sgst" numeric NOT NULL DEFAULT 0,"igst" numeric NOT NULL DEFAULT 0,"total" numeric NOT NULL DEFAULT 0,"status" text NOT NULL DEFAULT 'DRAFT'::text,"approval_status" text NOT NULL DEFAULT 'DRAFT'::text,"approval_token" text,"approver_name" text,"approver_notes" text,"approved_at" timestamp with time zone,"rejected_at" timestamp with time zone,"rejection_reason" text,"sent_to_customer_at" timestamp with time zone,"created_by" text,"created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()),"updated_at" timestamp with time zone DEFAULT timezone('utc'::text, now()));
ALTER TABLE public.crm_quotations ADD CONSTRAINT crm_quotations_pkey PRIMARY KEY (id);
ALTER TABLE public.lead_activities ADD CONSTRAINT lead_activities_pkey PRIMARY KEY (id);
ALTER TABLE public.document_items ADD CONSTRAINT document_items_pkey PRIMARY KEY (id);
ALTER TABLE public.comparison_document_data ADD CONSTRAINT comparison_document_data_document_id_key UNIQUE (document_id);
ALTER TABLE public.comparison_document_data ADD CONSTRAINT comparison_document_data_pkey PRIMARY KEY (id);
ALTER TABLE public.leads ADD CONSTRAINT leads_lead_source_check CHECK ((lead_source = ANY (ARRAY['facebook'::text, 'instagram'::text, 'whatsapp_bulk'::text, 'website'::text, 'bulk_email'::text, 'existing_customer'::text, 'phone'::text, 'referral'::text, 'other'::text])));
ALTER TABLE public.leads ADD CONSTRAINT leads_pkey PRIMARY KEY (id);
ALTER TABLE public.leads ADD CONSTRAINT leads_priority_check CHECK ((priority = ANY (ARRAY['hot'::text, 'warm'::text, 'cold'::text])));
ALTER TABLE public.leads ADD CONSTRAINT leads_status_check CHECK ((status = ANY (ARRAY['new'::text, 'telecaller_working'::text, 'requirement_collected'::text, 'sent_to_admin'::text, 'quotation_preparing'::text, 'waiting_owner_approval'::text, 'quotation_sent'::text, 'follow_up'::text, 'confirmed'::text, 'lost'::text, 'future'::text, 'owner_handover'::text])));
ALTER TABLE public.profiles ADD CONSTRAINT profiles_pkey PRIMARY KEY (id);
ALTER TABLE public.documents ADD CONSTRAINT documents_company_number_unique UNIQUE (company_id, document_number);
ALTER TABLE public.documents ADD CONSTRAINT documents_pkey PRIMARY KEY (id);
ALTER TABLE public.follow_ups ADD CONSTRAINT follow_ups_pkey PRIMARY KEY (id);
ALTER TABLE public.follow_ups ADD CONSTRAINT follow_ups_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'cancelled'::text])));
CREATE TABLE public.customers(id uuid PRIMARY KEY,company_id uuid REFERENCES public.profiles(id));
CREATE TABLE public.services(id uuid PRIMARY KEY,company_id uuid REFERENCES public.profiles(id));
ALTER TABLE public.crm_quotations ADD CONSTRAINT crm_quotations_company_id_fkey FOREIGN KEY (company_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.crm_quotations ADD CONSTRAINT crm_quotations_lead_id_fkey FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE SET NULL;
ALTER TABLE public.lead_activities ADD CONSTRAINT lead_activities_company_id_fkey FOREIGN KEY (company_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.lead_activities ADD CONSTRAINT lead_activities_lead_id_fkey FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE;
ALTER TABLE public.document_items ADD CONSTRAINT document_items_document_id_fkey FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE;
ALTER TABLE public.document_items ADD CONSTRAINT document_items_service_id_fkey FOREIGN KEY (service_id) REFERENCES services(id) ON DELETE SET NULL;
ALTER TABLE public.comparison_document_data ADD CONSTRAINT comparison_document_data_document_id_fkey FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE;
ALTER TABLE public.leads ADD CONSTRAINT leads_company_id_fkey FOREIGN KEY (company_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.leads ADD CONSTRAINT leads_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public.documents ADD CONSTRAINT documents_company_id_fkey FOREIGN KEY (company_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.documents ADD CONSTRAINT documents_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL;
ALTER TABLE public.documents ADD CONSTRAINT documents_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public.follow_ups ADD CONSTRAINT follow_ups_company_id_fkey FOREIGN KEY (company_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.follow_ups ADD CONSTRAINT follow_ups_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
